+/// A guard that, when dropped while the current thread is panicking, tells all
+/// workers to quit immediately.
+struct QuitOnPanic {
+    quit_now: Arc<AtomicBool>,
+}
+
+impl Drop for QuitOnPanic {
+    fn drop(&mut self) {
+        if std::thread::panicking() {
+            self.quit_now.store(true, AtomicOrdering::SeqCst);
+        }
+    }
+}
